window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3337a4f045fa58ad"]={"versions": [{"id": "FIG-3337a4f045fa58ad", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Composite Structure Diagram (UML 2.0 Profil für AUTOSAR VFB).\n</li><li><strong>Technischer Zweck:</strong> Formale Beschreibung der logischen Software-Architektur auf Ebene des Virtual Functional Bus (VFB) gemäß <code>AUTOSAR_SWS_VFB</code> (R3.0.7 / R3.1.5).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der ECU-unabhängigen Spezifikation von Software-Komponenten-Instanzen (<code>SwComponentPrototype</code>), deren Schnittstellen (Ports) und den wechselseitigen Bindungen über Assembly-Konnektoren (<code>AssemblySwConnector</code>). Das Modell abstrahiert vollständig von der späteren Verteilung (Mapping) auf physische Steuergeräte und bildet die Eingangsgröße für den RTE-Contract- und Generation-Pass.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten-Instanzen (<code>SwComponentPrototype</code> : <code>SwComponentType</code>)</h5>\n<p class=\"fig-p\">Dargestellt sind 7 Komponenten-Instanzen zweier funktionaler Klassen (erkennbar an den Top-Right-Icons):</p>\n<ol class=\"fig-list\"><li><strong>Application SWCs (Rechteck-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft : SeatHeatingControl</code> (Sitzheizungs-Steuerung links)\n</li><li><code>SHCFrontRight : SeatHeatingControl</code> (Sitzheizungs-Steuerung rechts)\n</li><li><code>PM : PowerManagement</code> (Zentrales Energiemanagement)\n</li></ul>\n</li><li><strong>Sensor/Actuator SWCs (Zeiger-/Skalen-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft : HeatingDial</code> (Bedienelement / Drehrad vorne links)\n</li><li><code>SHDialFrontRight : HeatingDial</code> (Bedienelement / Drehrad vorne rechts)\n</li><li><code>SHFrontLeft : SeatHeating</code> (Heizelement / Endstufe links)\n</li><li><code>SHFrontRight : SeatHeating</code> (Heizelement / Endstufe rechts)\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Assembly-Konnektoren (8 Verbindungen) &amp; Kommunikationsparadigmen</h5>\n<ul class=\"fig-list\"><li><strong>Client-Server-Konnektoren (C/S – Lollipop/Socket-Notation):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft.Position</code> (RPort, Client) → <code>SHCFrontLeft.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHDialFrontRight.Position</code> (RPort, Client) → <code>SHCFrontRight.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontLeft.HeatingElement</code> (RPort, Client) → <code>SHFrontLeft</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontRight.HeatingElement</code> (RPort, Client) → <code>SHFrontRight</code> (PPort, Server) [1:1]\n</li></ul>\n</li><li><strong>Sender-Receiver-Konnektoren (S/R – Pfeilsymbolik im Quadrat):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft.DialLED</code> (PPort, Sender) → <code>SHDialFrontLeft.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>SHCFrontRight.DialLED</code> (PPort, Sender) → <code>SHDialFrontRight.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontLeft.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontRight.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Offene / Nicht-verbundene Schnittstellen</h5>\n<ul class=\"fig-list\"><li><strong>Hardware-/BSW-spezifische Ports (konform zu Sensor/Actuator bzw. Basis-Software-Bindung):</strong>\n<ul class=\"fig-list\"><li><code>IO</code>: Direkte I/O-Hardware-Abstraktions-Ports (IOHwAb) an allen vier Sensor/Actuator-SWCs.\n</li><li><code>nv</code>: Non-Volatile-Memory-Ports (NvM-Schnittstelle) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>ecuMode</code>: Mode-Management-Schnittstellen (EcuM / BswM) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>Calibration</code>: Schnittstelle für Kalibrierparameter (<code>ParameterDataPrototype</code> / Component-internal).\n</li><li><code>SeatSwitch</code>: RPort für Sitzbelegungserkennung an <code>SeatHeatingControl</code>.\n</li><li><code>WindowDefrost</code>, <code>PowerStatus</code>: PPorts für weitere Subsysteme an <code>PM</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmuster &amp; Triggermechanismen</h5>\n<ol class=\"fig-list\"><li><strong>Sollwertvorgabe via Client-Server (C/S):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zustandsänderung am Bedienelement <code>SHDialFrontLeft</code> löst clientseitig einen Operationsaufruf an Port <code>Position</code> aus.\n</li><li><strong>Ablauf:</strong> Aufruf von <code>Rte_Call_Position_&lt;Operation&gt;()</code>. Am Server-Port <code>Setting</code> von <code>SHCFrontLeft</code> wird ein <code>OperationInvokedEvent</code> gefeuert; die zugeordnete Server-Runnable wird synchron (im Kontext des Aufrufers) oder asynchron (über OS-Taskaktivierung) ausgeführt.\n</li></ul>\n</li><li><strong>Freigabe / Leistungsbegrenzung via 1:n S/R-Multicast:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zyklisch oder ereignisgesteuert via <code>PM</code> (<code>PowerManagement</code>).\n</li><li><strong>Ablauf:</strong> <code>PM</code> schreibt über <code>Rte_Write_SeatHeating_&lt;DataElement&gt;()</code>. Die RTE verteilt den Wert parallel an die Receiver-Ports <code>PowerManagement</code> beider Instanzen (<code>SHCFrontLeft</code>, <code>SHCFrontRight</code>). Dort wird wahlweise ein <code>DataReceivedEvent</code> getriggert oder der Wert gepuffert zyklisch per <code>Rte_Read</code> abgefragt.\n</li></ul>\n</li><li><strong>Aktuatoransteuerung:</strong>\n<ul class=\"fig-list\"><li>Nach Abgleich zwischen Bedienerwunsch (<code>Setting</code>), Freigabe (<code>PowerManagement</code>) und Sitzkontakt (<code>SeatSwitch</code>) steuert <code>SHCFrontLeft</code> über den Client-Port <code>HeatingElement</code> den Server-Port der Leistungsendstufe <code>SHFrontLeft</code> an.\n</li></ul>\n</li><li><strong>Optische Rückmeldung (S/R 1:1):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft</code> aktualisiert über PPort <code>DialLED</code> (<code>Rte_Write</code>) den Status der Anzeige-LED an <code>SHDialFrontLeft.LED</code> (<code>Rte_Read</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Fehlerbehandlung &amp; Statusrückgaben</h5>\n<ul class=\"fig-list\"><li>C/S-Aufrufe liefern mindestens den RTE-Infrastrukturstatus (<code>RTE_E_OK</code>, <code>RTE_E_TIMEOUT</code>, <code>RTE_E_UNCONNECTED</code>) sowie optional modellierte <code>ApplicationErrors</code> zurück.\n</li><li>Bei Ausfall des Multicast-Signals <code>SeatHeating</code> greifen an den Receiver-Ports parametrierte <code>InitValues</code> oder Alive-Timeout-Überwachungen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Location-Independence &amp; RTE-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Die dargestellten Assembly-Konnektoren sind rein logisch. Werden z. B. <code>PM</code> und <code>SHCFrontLeft</code> auf dieselbe ECU gemappt (Intra-ECU), generiert der RTE-Generator speicherbasierte Puffer oder Direktaufrufe (inkl. OS-Interruptsperren/Spinlocks bei Taskgrenzen).\n</li><li>Werden sie auf getrennte ECUs partitioniert (Inter-ECU), transformiert der Toolchain-Generator die Assembly-Verbindung automatisch in Signale des AUTOSAR COM-Stacks (<code>Com_SendSignal</code>, PDUs, CAN/LIN/FlexRay), ohne dass der C-Code der SWC modifiziert werden muss.\n</li></ul>\n</li><li><strong>1:n Multicast bei Sender-Receiver:</strong>\n<ul class=\"fig-list\"><li>Ein PPort darf normativ mit beliebig vielen RPorts verbunden werden. Die RTE übernimmt die Duplizierung der Datenpakete. Pufferungsstrategien (Last-Is-Best vs. FIFO-Queuing) werden im Port-Interface / DataElement definiert.\n</li></ul>\n</li><li><strong>Restriktion für Sensor/Actuator-SWCs:</strong>\n<ul class=\"fig-list\"><li>Komponenten mit dem Typ <code>SensorActuatorSoftwareComponentType</code> (hier <code>HeatingDial</code>, <code>SeatHeating</code>) dürfen laut AUTOSAR-Regelwerk direkt an die Basissoftware (Ports <code>IO</code> zur IOHwAb) angebunden werden, müssen jedoch strikt an das physische Steuergerät gebunden sein, an dem die Hardware-Pins verdrahtet sind.\n</li><li>Standard Application SWCs (<code>SeatHeatingControl</code>, <code>PowerManagement</code>) besitzen keine direkten HW-Abhängigkeiten und bleiben frei allozierbar.\n</li></ul>\n</li><li><strong>Reentrancy bei Client-Server-Ports:</strong>\n<ul class=\"fig-list\"><li>Obwohl hier 1:1 dargestellt, erfordert die Anbindung mehrerer Client-RPorts an denselben Server-PPort entweder eine reentrante Implementierung der Server-Runnable (<code>canBeInvokedConcurrently = true</code>) oder eine Pufferung/Serialisierung über RTE- und OS-Task-Warteschlangen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-55b9c79599ee40e0", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Composite Structure Diagram (UML 2.0 Profil für AUTOSAR VFB).\n</li><li><strong>Technischer Zweck:</strong> Formale Beschreibung der logischen Software-Architektur auf Ebene des Virtual Functional Bus (VFB) gemäß <code>AUTOSAR_SWS_VFB</code> (R3.0.7 / R3.1.5).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der ECU-unabhängigen Spezifikation von Software-Komponenten-Instanzen (<code>SwComponentPrototype</code>), deren Schnittstellen (Ports) und den wechselseitigen Bindungen über Assembly-Konnektoren (<code>AssemblySwConnector</code>). Das Modell abstrahiert vollständig von der späteren Verteilung (Mapping) auf physische Steuergeräte und bildet die Eingangsgröße für den RTE-Contract- und Generation-Pass.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten-Instanzen (<code>SwComponentPrototype</code> : <code>SwComponentType</code>)</h5>\n<p class=\"fig-p\">Dargestellt sind 7 Komponenten-Instanzen zweier funktionaler Klassen (erkennbar an den Top-Right-Icons):</p>\n<ol class=\"fig-list\"><li><strong>Application SWCs (Rechteck-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft : SeatHeatingControl</code> (Sitzheizungs-Steuerung links)\n</li><li><code>SHCFrontRight : SeatHeatingControl</code> (Sitzheizungs-Steuerung rechts)\n</li><li><code>PM : PowerManagement</code> (Zentrales Energiemanagement)\n</li></ul>\n</li><li><strong>Sensor/Actuator SWCs (Zeiger-/Skalen-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft : HeatingDial</code> (Bedienelement / Drehrad vorne links)\n</li><li><code>SHDialFrontRight : HeatingDial</code> (Bedienelement / Drehrad vorne rechts)\n</li><li><code>SHFrontLeft : SeatHeating</code> (Heizelement / Endstufe links)\n</li><li><code>SHFrontRight : SeatHeating</code> (Heizelement / Endstufe rechts)\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Assembly-Konnektoren (8 Verbindungen) &amp; Kommunikationsparadigmen</h5>\n<ul class=\"fig-list\"><li><strong>Client-Server-Konnektoren (C/S – Lollipop/Socket-Notation):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft.Position</code> (RPort, Client) → <code>SHCFrontLeft.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHDialFrontRight.Position</code> (RPort, Client) → <code>SHCFrontRight.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontLeft.HeatingElement</code> (RPort, Client) → <code>SHFrontLeft</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontRight.HeatingElement</code> (RPort, Client) → <code>SHFrontRight</code> (PPort, Server) [1:1]\n</li></ul>\n</li><li><strong>Sender-Receiver-Konnektoren (S/R – Pfeilsymbolik im Quadrat):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft.DialLED</code> (PPort, Sender) → <code>SHDialFrontLeft.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>SHCFrontRight.DialLED</code> (PPort, Sender) → <code>SHDialFrontRight.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontLeft.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontRight.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Offene / Nicht-verbundene Schnittstellen</h5>\n<ul class=\"fig-list\"><li><strong>Hardware-/BSW-spezifische Ports (konform zu Sensor/Actuator bzw. Basis-Software-Bindung):</strong>\n<ul class=\"fig-list\"><li><code>IO</code>: Direkte I/O-Hardware-Abstraktions-Ports (IOHwAb) an allen vier Sensor/Actuator-SWCs.\n</li><li><code>nv</code>: Non-Volatile-Memory-Ports (NvM-Schnittstelle, dargestellt mit Dreiecks-Symbol) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>ecuMode</code>: Mode-Management-Schnittstellen (EcuM / BswM, dargestellt mit Dreiecks-Symbol) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>Calibration</code>: Schnittstelle für Kalibrierparameter (<code>ParameterDataPrototype</code> / Component-internal).\n</li><li><code>SeatSwitch</code>: RPort für Sitzbelegungserkennung an <code>SeatHeatingControl</code>.\n</li><li><code>WindowDefrost</code>, <code>PowerStatus</code>: PPorts für weitere Subsysteme an <code>PM</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmuster &amp; Triggermechanismen</h5>\n<ol class=\"fig-list\"><li><strong>Sollwertvorgabe via Client-Server (C/S):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zustandsänderung am Bedienelement <code>SHDialFrontLeft</code> löst clientseitig einen Operationsaufruf an Port <code>Position</code> aus.\n</li><li><strong>Ablauf:</strong> Aufruf von <code>Rte_Call_Position_&lt;Operation&gt;()</code>. Am Server-Port <code>Setting</code> von <code>SHCFrontLeft</code> wird ein <code>OperationInvokedEvent</code> gefeuert; die zugeordnete Server-Runnable wird synchron (im Kontext des Aufrufers) oder asynchron (über OS-Taskaktivierung) ausgeführt.\n</li></ul>\n</li><li><strong>Freigabe / Leistungsbegrenzung via 1:n S/R-Multicast:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zyklisch oder ereignisgesteuert via <code>PM</code> (<code>PowerManagement</code>).\n</li><li><strong>Ablauf:</strong> <code>PM</code> schreibt über <code>Rte_Write_SeatHeating_&lt;DataElement&gt;()</code>. Die RTE verteilt den Wert parallel an die Receiver-Ports <code>PowerManagement</code> beider Instanzen (<code>SHCFrontLeft</code>, <code>SHCFrontRight</code>). Dort wird wahlweise ein <code>DataReceivedEvent</code> getriggert oder der Wert gepuffert zyklisch per <code>Rte_Read</code> abgefragt.\n</li></ul>\n</li><li><strong>Aktuatoransteuerung:</strong>\n<ul class=\"fig-list\"><li>Nach Abgleich zwischen Bedienerwunsch (<code>Setting</code>), Freigabe (<code>PowerManagement</code>) und Sitzkontakt (<code>SeatSwitch</code>) steuert <code>SHCFrontLeft</code> über den Client-Port <code>HeatingElement</code> den Server-Port der Leistungsendstufe <code>SHFrontLeft</code> an.\n</li></ul>\n</li><li><strong>Optische Rückmeldung (S/R 1:1):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft</code> aktualisiert über PPort <code>DialLED</code> (<code>Rte_Write</code>) den Status der Anzeige-LED an <code>SHDialFrontLeft.LED</code> (<code>Rte_Read</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Fehlerbehandlung &amp; Statusrückgaben</h5>\n<ul class=\"fig-list\"><li>C/S-Aufrufe liefern mindestens den RTE-Infrastrukturstatus (<code>RTE_E_OK</code>, <code>RTE_E_TIMEOUT</code>, <code>RTE_E_UNCONNECTED</code>) sowie optional modellierte <code>ApplicationErrors</code> zurück.\n</li><li>Bei Ausfall des Multicast-Signals <code>SeatHeating</code> greifen an den Receiver-Ports parametrierte <code>InitValues</code> oder Alive-Timeout-Überwachungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Location-Independence &amp; RTE-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Die dargestellten Assembly-Konnektoren sind rein logisch. Werden z. B. <code>PM</code> und <code>SHCFrontLeft</code> auf dieselbe ECU gemappt (Intra-ECU), generiert der RTE-Generator speicherbasierte Puffer oder Direktaufrufe (inkl. OS-Interruptsperren/Spinlocks bei Taskgrenzen).\n</li><li>Werden sie auf getrennte ECUs partitioniert (Inter-ECU), transformiert der Toolchain-Generator die Assembly-Verbindung automatisch in Signale des AUTOSAR COM-Stacks (<code>Com_SendSignal</code>, PDUs, CAN/LIN/FlexRay), ohne dass der C-Code der SWC modifiziert werden muss.\n</li></ul>\n</li><li><strong>1:n Multicast bei Sender-Receiver:</strong>\n<ul class=\"fig-list\"><li>Ein PPort darf normativ mit beliebig vielen RPorts verbunden werden. Die RTE übernimmt die Duplizierung der Datenpakete. Pufferungsstrategien (Last-Is-Best vs. FIFO-Queuing) werden im Port-Interface / DataElement definiert.\n</li></ul>\n</li><li><strong>Restriktion für Sensor/Actuator-SWCs:</strong>\n<ul class=\"fig-list\"><li>Komponenten mit dem Typ <code>SensorActuatorSoftwareComponentType</code> (hier <code>HeatingDial</code>, <code>SeatHeating</code>) dürfen laut AUTOSAR-Regelwerk direkt an die Basissoftware (Ports <code>IO</code> zur IOHwAb) angebunden werden, müssen jedoch strikt an das physische Steuergerät gebunden sein, an dem die Hardware-Pins verdrahtet sind.\n</li><li>Standard Application SWCs (<code>SeatHeatingControl</code>, <code>PowerManagement</code>) besitzen keine direkten HW-Abhängigkeiten und bleiben frei allozierbar.\n</li></ul>\n</li><li><strong>Reentrancy bei Client-Server-Ports:</strong>\n<ul class=\"fig-list\"><li>Obwohl hier 1:1 dargestellt, erfordert die Anbindung mehrerer Client-RPorts an denselben Server-PPort entweder eine reentrante Implementierung der Server-Runnable (<code>canBeInvokedConcurrently = true</code>) oder eine Pufferung/Serialisierung über RTE- und OS-Task-Warteschlangen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-c16909950dae22b7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Composite Structure Diagram (UML 2.0 Profil für AUTOSAR VFB).\n</li><li><strong>Technischer Zweck:</strong> Formale Beschreibung der logischen Software-Architektur auf Ebene des Virtual Functional Bus (VFB) gemäß <code>AUTOSAR_SWS_VFB</code> (R3.0.7 / R3.1.5).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der ECU-unabhängigen Spezifikation von Software-Komponenten-Instanzen (<code>SwComponentPrototype</code>), deren Schnittstellen (Ports) und den wechselseitigen Bindungen über Assembly-Konnektoren (<code>AssemblySwConnector</code>). Das Modell abstrahiert vollständig von der späteren Verteilung (Mapping) auf physische Steuergeräte und bildet die Eingangsgröße für den RTE-Contract- und Generation-Pass.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten-Instanzen (<code>SwComponentPrototype</code> : <code>SwComponentType</code>)</h5>\n<p class=\"fig-p\">Dargestellt sind 7 Komponenten-Instanzen zweier funktionaler Klassen (erkennbar an den Top-Right-Icons):</p>\n<ol class=\"fig-list\"><li><strong>Application SWCs (Rechteck-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft : SeatHeatingControl</code> (Sitzheizungs-Steuerung links)\n</li><li><code>SHCFrontRight : SeatHeatingControl</code> (Sitzheizungs-Steuerung rechts)\n</li><li><code>PM : PowerManagement</code> (Zentrales Energiemanagement)\n</li></ul>\n</li><li><strong>Sensor/Actuator SWCs (Zeiger-/Skalen-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft : HeatingDial</code> (Bedienelement / Drehrad vorne links)\n</li><li><code>SHDialFrontRight : HeatingDial</code> (Bedienelement / Drehrad vorne rechts)\n</li><li><code>SHFrontLeft : SeatHeating</code> (Heizelement / Endstufe links)\n</li><li><code>SHFrontRight : SeatHeating</code> (Heizelement / Endstufe rechts)\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Assembly-Konnektoren (8 Verbindungen) &amp; Kommunikationsparadigmen</h5>\n<ul class=\"fig-list\"><li><strong>Client-Server-Konnektoren (C/S – Lollipop/Socket-Notation):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft.Position</code> (RPort, Client) → <code>SHCFrontLeft.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHDialFrontRight.Position</code> (RPort, Client) → <code>SHCFrontRight.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontLeft.HeatingElement</code> (RPort, Client) → <code>SHFrontLeft</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontRight.HeatingElement</code> (RPort, Client) → <code>SHFrontRight</code> (PPort, Server) [1:1]\n</li></ul>\n</li><li><strong>Sender-Receiver-Konnektoren (S/R – Pfeilsymbolik im Quadrat):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft.DialLED</code> (PPort, Sender) → <code>SHDialFrontLeft.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>SHCFrontRight.DialLED</code> (PPort, Sender) → <code>SHDialFrontRight.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontLeft.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontRight.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Offene / Nicht-verbundene Schnittstellen</h5>\n<ul class=\"fig-list\"><li><strong>Hardware-/BSW-spezifische Ports (konform zu Sensor/Actuator bzw. Basis-Software-Bindung):</strong>\n<ul class=\"fig-list\"><li><code>IO</code>: Direkte I/O-Hardware-Abstraktions-Ports (IOHwAb) an allen vier Sensor/Actuator-SWCs.\n</li><li><code>nv</code>: Non-Volatile-Memory-Ports (NvM-Schnittstelle, dargestellt mit Dreiecks-Symbol) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>ecuMode</code>: Mode-Management-Schnittstellen (EcuM / BswM, dargestellt mit Mode-Switch-Symbol / Quadrat mit drei Punkten) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>Calibration</code>: Schnittstelle für Kalibrierparameter (<code>ParameterDataPrototype</code> / Component-internal).\n</li><li><code>SeatSwitch</code>: RPort für Sitzbelegungserkennung an <code>SeatHeatingControl</code>.\n</li><li><code>WindowDefrost</code>, <code>PowerStatus</code>: PPorts für weitere Subsysteme an <code>PM</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmuster &amp; Triggermechanismen</h5>\n<ol class=\"fig-list\"><li><strong>Sollwertvorgabe via Client-Server (C/S):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zustandsänderung am Bedienelement <code>SHDialFrontLeft</code> löst clientseitig einen Operationsaufruf an Port <code>Position</code> aus.\n</li><li><strong>Ablauf:</strong> Aufruf von <code>Rte_Call_Position_&lt;Operation&gt;()</code>. Am Server-Port <code>Setting</code> von <code>SHCFrontLeft</code> wird ein <code>OperationInvokedEvent</code> gefeuert; die zugeordnete Server-Runnable wird synchron (im Kontext des Aufrufers) oder asynchron (über OS-Taskaktivierung) ausgeführt.\n</li></ul>\n</li><li><strong>Freigabe / Leistungsbegrenzung via 1:n S/R-Multicast:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zyklisch oder ereignisgesteuert via <code>PM</code> (<code>PowerManagement</code>).\n</li><li><strong>Ablauf:</strong> <code>PM</code> schreibt über <code>Rte_Write_SeatHeating_&lt;DataElement&gt;()</code>. Die RTE verteilt den Wert parallel an die Receiver-Ports <code>PowerManagement</code> beider Instanzen (<code>SHCFrontLeft</code>, <code>SHCFrontRight</code>). Dort wird wahlweise ein <code>DataReceivedEvent</code> getriggert oder der Wert gepuffert zyklisch per <code>Rte_Read</code> abgefragt.\n</li></ul>\n</li><li><strong>Aktuatoransteuerung:</strong>\n<ul class=\"fig-list\"><li>Nach Abgleich zwischen Bedienerwunsch (<code>Setting</code>), Freigabe (<code>PowerManagement</code>) und Sitzkontakt (<code>SeatSwitch</code>) steuert <code>SHCFrontLeft</code> über den Client-Port <code>HeatingElement</code> den Server-Port der Leistungsendstufe <code>SHFrontLeft</code> an.\n</li></ul>\n</li><li><strong>Optische Rückmeldung (S/R 1:1):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft</code> aktualisiert über PPort <code>DialLED</code> (<code>Rte_Write</code>) den Status der Anzeige-LED an <code>SHDialFrontLeft.LED</code> (<code>Rte_Read</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Fehlerbehandlung &amp; Statusrückgaben</h5>\n<ul class=\"fig-list\"><li>C/S-Aufrufe liefern mindestens den RTE-Infrastrukturstatus (<code>RTE_E_OK</code>, <code>RTE_E_TIMEOUT</code>, <code>RTE_E_UNCONNECTED</code>) sowie optional modellierte <code>ApplicationErrors</code> zurück.\n</li><li>Bei Ausfall des Multicast-Signals <code>SeatHeating</code> greifen an den Receiver-Ports parametrierte <code>InitValues</code> oder Alive-Timeout-Überwachungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Location-Independence &amp; RTE-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Die dargestellten Assembly-Konnektoren sind rein logisch. Werden z. B. <code>PM</code> und <code>SHCFrontLeft</code> auf dieselbe ECU gemappt (Intra-ECU), generiert der RTE-Generator speicherbasierte Puffer oder Direktaufrufe (inkl. OS-Interruptsperren/Spinlocks bei Taskgrenzen).\n</li><li>Werden sie auf getrennte ECUs partitioniert (Inter-ECU), transformiert der Toolchain-Generator die Assembly-Verbindung automatisch in Signale des AUTOSAR COM-Stacks (<code>Com_SendSignal</code>, PDUs, CAN/LIN/FlexRay), ohne dass der C-Code der SWC modifiziert werden muss.\n</li></ul>\n</li><li><strong>1:n Multicast bei Sender-Receiver:</strong>\n<ul class=\"fig-list\"><li>Ein PPort darf normativ mit beliebig vielen RPorts verbunden werden. Die RTE übernimmt die Duplizierung der Datenpakete. Pufferungsstrategien (Last-Is-Best vs. FIFO-Queuing) werden im Port-Interface / DataElement definiert.\n</li></ul>\n</li><li><strong>Restriktion für Sensor/Actuator-SWCs:</strong>\n<ul class=\"fig-list\"><li>Komponenten mit dem Typ <code>SensorActuatorSoftwareComponentType</code> (hier <code>HeatingDial</code>, <code>SeatHeating</code>) dürfen laut AUTOSAR-Regelwerk direkt an die Basissoftware (Ports <code>IO</code> zur IOHwAb) angebunden werden, müssen jedoch strikt an das physische Steuergerät gebunden sein, an dem die Hardware-Pins verdrahtet sind.\n</li><li>Standard Application SWCs (<code>SeatHeatingControl</code>, <code>PowerManagement</code>) besitzen keine direkten HW-Abhängigkeiten und bleiben frei allozierbar.\n</li></ul>\n</li><li><strong>Reentrancy bei Client-Server-Ports:</strong>\n<ul class=\"fig-list\"><li>Obwohl hier 1:1 dargestellt, erfordert die Anbindung mehrerer Client-RPorts an denselben Server-PPort entweder eine reentrante Implementierung der Server-Runnable (<code>canBeInvokedConcurrently = true</code>) oder eine Pufferung/Serialisierung über RTE- und OS-Task-Warteschlangen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-36c5bcf8a93ffcd2", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Composite Structure Diagram (UML 2.0 Profil für AUTOSAR VFB).\n</li><li><strong>Technischer Zweck:</strong> Formale Beschreibung der logischen Software-Architektur auf Ebene des Virtual Functional Bus (VFB) gemäß <code>AUTOSAR_SWS_VFB</code> (R3.0.7 / R3.1.5).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der ECU-unabhängigen Spezifikation von Software-Komponenten-Instanzen (<code>SwComponentPrototype</code>), deren Schnittstellen (Ports) und den wechselseitigen Bindungen über Assembly-Konnektoren (<code>AssemblySwConnector</code>). Das Modell abstrahiert vollständig von der späteren Verteilung (Mapping) auf physische Steuergeräte und bildet die Eingangsgröße für den RTE-Contract- und Generation-Pass.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten-Instanzen (<code>SwComponentPrototype</code> : <code>SwComponentType</code>)</h5>\n<p class=\"fig-p\">Dargestellt sind 7 Komponenten-Instanzen zweier funktionaler Klassen (erkennbar an den Top-Right-Icons):</p>\n<ol class=\"fig-list\"><li><strong>Application SWCs (Rechteck-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft : SeatHeatingControl</code> (Sitzheizungs-Steuerung links)\n</li><li><code>SHCFrontRight : SeatHeatingControl</code> (Sitzheizungs-Steuerung rechts)\n</li><li><code>PM : PowerManagement</code> (Zentrales Energiemanagement)\n</li></ul>\n</li><li><strong>Sensor/Actuator SWCs (Zeiger-/Skalen-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft : HeatingDial</code> (Bedienelement / Drehrad vorne links)\n</li><li><code>SHDialFrontRight : HeatingDial</code> (Bedienelement / Drehrad vorne rechts)\n</li><li><code>SHFrontLeft : SeatHeating</code> (Heizelement / Endstufe links)\n</li><li><code>SHFrontRight : SeatHeating</code> (Heizelement / Endstufe rechts)\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Assembly-Konnektoren (8 Verbindungen) &amp; Kommunikationsparadigmen</h5>\n<ul class=\"fig-list\"><li><strong>Client-Server-Konnektoren (C/S – Lollipop/Socket-Notation):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft.Position</code> (RPort, Client) → <code>SHCFrontLeft.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHDialFrontRight.Position</code> (RPort, Client) → <code>SHCFrontRight.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontLeft.HeatingElement</code> (RPort, Client) → <code>SHFrontLeft</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontRight.HeatingElement</code> (RPort, Client) → <code>SHFrontRight</code> (PPort, Server) [1:1]\n</li></ul>\n</li><li><strong>Sender-Receiver-Konnektoren (S/R – Pfeilsymbolik im Quadrat):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft.DialLED</code> (PPort, Sender) → <code>SHDialFrontLeft.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>SHCFrontRight.DialLED</code> (PPort, Sender) → <code>SHDialFrontRight.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontLeft.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontRight.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Offene / Nicht-verbundene Schnittstellen</h5>\n<ul class=\"fig-list\"><li><strong>Hardware-/BSW-spezifische Ports (konform zu Sensor/Actuator bzw. Basis-Software-Bindung):</strong>\n<ul class=\"fig-list\"><li><code>IO</code>: Direkte I/O-Hardware-Abstraktions-Ports (IOHwAb) an allen vier Sensor/Actuator-SWCs.\n</li><li><code>nv</code>: Non-Volatile-Memory-Ports (NvM-Schnittstelle, dargestellt mit Dreiecks-Symbol) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>ecuMode</code>: Mode-Management-Schnittstellen (EcuM / BswM, dargestellt mit Mode-Switch-Symbol / Quadrat mit drei Punkten) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>Calibration</code>: Schnittstelle für Kalibrierparameter (<code>ParameterDataPrototype</code> / Component-internal).\n</li><li><code>SeatSwitch</code>: RPort für Sitzbelegungserkennung an <code>SeatHeatingControl</code>.\n</li><li><code>WindowDefrost</code>, <code>PowerStatus</code>: PPorts für weitere Subsysteme an <code>PM</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmuster &amp; Triggermechanismen</h5>\n<ol class=\"fig-list\"><li><strong>Sollwertvorgabe via Client-Server (C/S):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zustandsänderung am Bedienelement <code>SHDialFrontLeft</code> löst clientseitig einen Operationsaufruf an Port <code>Position</code> aus.\n</li><li><strong>Ablauf:</strong> Aufruf von <code>Rte_Call_Position_&lt;Operation&gt;()</code>. Am Server-Port <code>Setting</code> von <code>SHCFrontLeft</code> wird ein <code>OperationInvokedEvent</code> gefeuert; die zugeordnete Server-Runnable wird synchron (im Kontext des Aufrufers) oder asynchron (über OS-Taskaktivierung) ausgeführt.\n</li></ul>\n</li><li><strong>Freigabe / Leistungsbegrenzung via 1:n S/R-Multicast:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zyklisch oder ereignisgesteuert via <code>PM</code> (<code>PowerManagement</code>).\n</li><li><strong>Ablauf:</strong> <code>PM</code> schreibt über <code>Rte_Write_SeatHeating_&lt;DataElement&gt;()</code>. Die RTE verteilt den Wert parallel an die Receiver-Ports <code>PowerManagement</code> beider Instanzen (<code>SHCFrontLeft</code>, <code>SHCFrontRight</code>). Dort wird wahlweise ein <code>DataReceivedEvent</code> getriggert oder der Wert gepuffert zyklisch per <code>Rte_Read</code> abgefragt.\n</li></ul>\n</li><li><strong>Aktuatoransteuerung:</strong>\n<ul class=\"fig-list\"><li>Nach Abgleich zwischen Bedienerwunsch (<code>Setting</code>), Freigabe (<code>PowerManagement</code>) und Sitzkontakt (<code>SeatSwitch</code>) steuert <code>SHCFrontLeft</code> über den Client-Port <code>HeatingElement</code> den Server-Port der Leistungsendstufe <code>SHFrontLeft</code> an.\n</li></ul>\n</li><li><strong>Optische Rückmeldung (S/R 1:1):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft</code> aktualisiert über PPort <code>DialLED</code> (<code>Rte_Write</code>) den Status der Anzeige-LED an <code>SHDialFrontLeft.LED</code> (<code>Rte_Read</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Fehlerbehandlung &amp; Statusrückgaben</h5>\n<ul class=\"fig-list\"><li>C/S-Aufrufe liefern mindestens den RTE-Infrastrukturstatus (<code>RTE_E_OK</code>, <code>RTE_E_TIMEOUT</code>, <code>RTE_E_UNCONNECTED</code>) sowie optional modellierte <code>ApplicationErrors</code> zurück.\n</li><li>Bei Ausfall des Multicast-Signals <code>SeatHeating</code> greifen an den Receiver-Ports parametrierte <code>InitValues</code> oder Alive-Timeout-Überwachungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Location-Independence &amp; RTE-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Die dargestellten Assembly-Konnektoren sind rein logisch. Werden z. B. <code>PM</code> und <code>SHCFrontLeft</code> auf dieselbe ECU gemappt (Intra-ECU), generiert der RTE-Generator speicherbasierte Puffer oder Direktaufrufe (inkl. OS-Interruptsperren/Spinlocks bei Taskgrenzen).\n</li><li>Werden sie auf getrennte ECUs partitioniert (Inter-ECU), transformiert der Toolchain-Generator die Assembly-Verbindung automatisch in Signale des AUTOSAR COM-Stacks (<code>Com_SendSignal</code>, PDUs, CAN/LIN/FlexRay), ohne dass der C-Code der SWC modifiziert werden muss.\n</li></ul>\n</li><li><strong>1:n Multicast bei Sender-Receiver:</strong>\n<ul class=\"fig-list\"><li>Ein PPort darf normativ mit beliebig vielen RPorts verbunden werden. Die RTE übernimmt die Duplizierung der Datenpakete. Pufferungsstrategien (Last-Is-Best vs. FIFO-Queuing) werden im Port-Interface / DataElement definiert.\n</li></ul>\n</li><li><strong>Restriktion für Sensor/Actuator-SWCs:</strong>\n<ul class=\"fig-list\"><li>Komponenten mit dem Typ <code>SensorActuatorSoftwareComponentType</code> (hier <code>HeatingDial</code>, <code>SeatHeating</code>) dürfen laut AUTOSAR-Regelwerk direkt an die Basissoftware (Ports <code>IO</code> zur IOHwAb) angebunden werden, müssen jedoch strikt an das physische Steuergerät gebunden sein, an dem die Hardware-Pins verdrahtet sind.\n</li><li>Standard Application SWCs (<code>SeatHeatingControl</code>, <code>PowerManagement</code>) besitzen keine direkten HW-Abhängigkeiten und bleiben frei allozierbar.\n</li></ul>\n</li><li><strong>Reentrancy bei Client-Server-Ports:</strong>\n<ul class=\"fig-list\"><li>Obwohl hier 1:1 dargestellt, erfordert die Anbindung mehrerer Client-RPorts an denselben Server-PPort entweder eine reentrante Implementierung der Server-Runnable (<code>canBeInvokedConcurrently = true</code>) oder eine Pufferung/Serialisierung über RTE- und OS-Task-Warteschlangen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f8833a57302019fb", "releases": ["R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR VFB-Komponentendiagramm / Composite Structure Diagram (UML 2.0 Profil für AUTOSAR VFB).\n</li><li><strong>Technischer Zweck:</strong> Formale Beschreibung der logischen Software-Architektur auf Ebene des Virtual Functional Bus (VFB) gemäß <code>AUTOSAR_SWS_VFB</code> (R3.0.7 / R3.1.5).\n</li><li><strong>Funktionale Einordnung:</strong> Dient der ECU-unabhängigen Spezifikation von Software-Komponenten-Instanzen (<code>SwComponentPrototype</code>), deren Schnittstellen (Ports) und den wechselseitigen Bindungen über Assembly-Konnektoren (<code>AssemblySwConnector</code>). Das Modell abstrahiert vollständig von der späteren Verteilung (Mapping) auf physische Steuergeräte und bildet die Eingangsgröße für den RTE-Contract- und Generation-Pass.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten-Instanzen (<code>SwComponentPrototype</code> : <code>SwComponentType</code>)</h5>\n<p class=\"fig-p\">Dargestellt sind 7 Komponenten-Instanzen zweier funktionaler Klassen (erkennbar an den Top-Right-Icons):</p>\n<ol class=\"fig-list\"><li><strong>Application SWCs (Rechteck-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft : SeatHeatingControl</code> (Sitzheizungs-Steuerung links)\n</li><li><code>SHCFrontRight : SeatHeatingControl</code> (Sitzheizungs-Steuerung rechts)\n</li><li><code>PM : PowerManagement</code> (Zentrales Energiemanagement)\n</li></ul>\n</li><li><strong>Sensor/Actuator SWCs (Zeiger-/Skalen-Symbol):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft : HeatingDial</code> (Bedienelement / Drehrad vorne links)\n</li><li><code>SHDialFrontRight : HeatingDial</code> (Bedienelement / Drehrad vorne rechts)\n</li><li><code>SHFrontLeft : SeatHeating</code> (Heizelement / Endstufe links)\n</li><li><code>SHFrontRight : SeatHeating</code> (Heizelement / Endstufe rechts)\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Assembly-Konnektoren (8 Verbindungen) &amp; Kommunikationsparadigmen</h5>\n<ul class=\"fig-list\"><li><strong>Client-Server-Konnektoren (C/S – Lollipop/Socket-Notation):</strong>\n<ul class=\"fig-list\"><li><code>SHDialFrontLeft.Position</code> (RPort, Client) → <code>SHCFrontLeft.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHDialFrontRight.Position</code> (RPort, Client) → <code>SHCFrontRight.Setting</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontLeft.HeatingElement</code> (RPort, Client) → <code>SHFrontLeft</code> (PPort, Server) [1:1]\n</li><li><code>SHCFrontRight.HeatingElement</code> (RPort, Client) → <code>SHFrontRight</code> (PPort, Server) [1:1]\n</li></ul>\n</li><li><strong>Sender-Receiver-Konnektoren (S/R – Pfeilsymbolik im Quadrat):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft.DialLED</code> (PPort, Sender) → <code>SHDialFrontLeft.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>SHCFrontRight.DialLED</code> (PPort, Sender) → <code>SHDialFrontRight.LED</code> (RPort, Receiver) [1:1]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontLeft.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li><li><code>PM.SeatHeating</code> (PPort, Sender) → <code>SHCFrontRight.PowerManagement</code> (RPort, Receiver) [1:n Multicast]\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Offene / Nicht-verbundene Schnittstellen</h5>\n<ul class=\"fig-list\"><li><strong>Hardware-/BSW-spezifische Ports (konform zu Sensor/Actuator bzw. Basis-Software-Bindung):</strong>\n<ul class=\"fig-list\"><li><code>IO</code>: Direkte I/O-Hardware-Abstraktions-Ports (IOHwAb) an allen vier Sensor/Actuator-SWCs.\n</li><li><code>nv</code>: Non-Volatile-Memory-Ports (NvM-Schnittstelle, dargestellt mit Dreiecks-Symbol) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>ecuMode</code>: Mode-Management-Schnittstellen (EcuM / BswM, dargestellt mit Mode-Switch-Symbol / Quadrat mit drei Punkten) an den <code>SeatHeatingControl</code>-Instanzen.\n</li><li><code>Calibration</code>: Schnittstelle für Kalibrierparameter (<code>ParameterDataPrototype</code> / Component-internal).\n</li><li><code>SeatSwitch</code>: RPort für Sitzbelegungserkennung an <code>SeatHeatingControl</code>.\n</li><li><code>WindowDefrost</code>, <code>PowerStatus</code>: PPorts für weitere Subsysteme an <code>PM</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Kommunikationsmuster &amp; Triggermechanismen</h5>\n<ol class=\"fig-list\"><li><strong>Sollwertvorgabe via Client-Server (C/S):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zustandsänderung am Bedienelement <code>SHDialFrontLeft</code> löst clientseitig einen Operationsaufruf an Port <code>Position</code> aus.\n</li><li><strong>Ablauf:</strong> Aufruf von <code>Rte_Call_Position_&lt;Operation&gt;()</code>. Am Server-Port <code>Setting</code> von <code>SHCFrontLeft</code> wird ein <code>OperationInvokedEvent</code> gefeuert; die zugeordnete Server-Runnable wird synchron (im Kontext des Aufrufers) oder asynchron (über OS-Taskaktivierung) ausgeführt.\n</li></ul>\n</li><li><strong>Freigabe / Leistungsbegrenzung via 1:n S/R-Multicast:</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Zyklisch oder ereignisgesteuert via <code>PM</code> (<code>PowerManagement</code>).\n</li><li><strong>Ablauf:</strong> <code>PM</code> schreibt über <code>Rte_Write_SeatHeating_&lt;DataElement&gt;()</code>. Die RTE verteilt den Wert parallel an die Receiver-Ports <code>PowerManagement</code> beider Instanzen (<code>SHCFrontLeft</code>, <code>SHCFrontRight</code>). Dort wird wahlweise ein <code>DataReceivedEvent</code> getriggert oder der Wert gepuffert zyklisch per <code>Rte_Read</code> abgefragt.\n</li></ul>\n</li><li><strong>Aktuatoransteuerung:</strong>\n<ul class=\"fig-list\"><li>Nach Abgleich zwischen Bedienerwunsch (<code>Setting</code>), Freigabe (<code>PowerManagement</code>) und Sitzkontakt (<code>SeatSwitch</code>) steuert <code>SHCFrontLeft</code> über den Client-Port <code>HeatingElement</code> den Server-Port der Leistungsendstufe <code>SHFrontLeft</code> an.\n</li></ul>\n</li><li><strong>Optische Rückmeldung (S/R 1:1):</strong>\n<ul class=\"fig-list\"><li><code>SHCFrontLeft</code> aktualisiert über PPort <code>DialLED</code> (<code>Rte_Write</code>) den Status der Anzeige-LED an <code>SHDialFrontLeft.LED</code> (<code>Rte_Read</code>).\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Fehlerbehandlung &amp; Statusrückgaben</h5>\n<ul class=\"fig-list\"><li>C/S-Aufrufe liefern mindestens den RTE-Infrastrukturstatus (<code>RTE_E_OK</code>, <code>RTE_E_TIMEOUT</code>, <code>RTE_E_UNCONNECTED</code>) sowie optional modellierte <code>ApplicationErrors</code> zurück.\n</li><li>Bei Ausfall des Multicast-Signals <code>SeatHeating</code> greifen an den Receiver-Ports parametrierte <code>InitValues</code> oder Alive-Timeout-Überwachungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Location-Independence &amp; RTE-Codegenerierung:</strong>\n<ul class=\"fig-list\"><li>Die dargestellten Assembly-Konnektoren sind rein logisch. Werden z. B. <code>PM</code> und <code>SHCFrontLeft</code> auf dieselbe ECU gemappt (Intra-ECU), generiert der RTE-Generator speicherbasierte Puffer oder Direktaufrufe (inkl. OS-Interruptsperren/Spinlocks bei Taskgrenzen).\n</li><li>Werden sie auf getrennte ECUs partitioniert (Inter-ECU), transformiert der Toolchain-Generator die Assembly-Verbindung automatisch in Signale des AUTOSAR COM-Stacks (<code>Com_SendSignal</code>, PDUs, CAN/LIN/FlexRay), ohne dass der C-Code der SWC modifiziert werden muss.\n</li></ul>\n</li><li><strong>1:n Multicast bei Sender-Receiver:</strong>\n<ul class=\"fig-list\"><li>Ein PPort darf normativ mit beliebig vielen RPorts verbunden werden. Die RTE übernimmt die Duplizierung der Datenpakete. Pufferungsstrategien (Last-Is-Best vs. FIFO-Queuing) werden im Port-Interface / DataElement definiert.\n</li></ul>\n</li><li><strong>Restriktion für Sensor/Actuator-SWCs:</strong>\n<ul class=\"fig-list\"><li>Komponenten mit dem Typ <code>SensorActuatorSoftwareComponentType</code> (hier <code>HeatingDial</code>, <code>SeatHeating</code>) dürfen laut AUTOSAR-Regelwerk direkt an die Basissoftware (Ports <code>IO</code> zur IOHwAb) angebunden werden, müssen jedoch strikt an das physische Steuergerät gebunden sein, an dem die Hardware-Pins verdrahtet sind.\n</li><li>Standard Application SWCs (<code>SeatHeatingControl</code>, <code>PowerManagement</code>) besitzen keine direkten HW-Abhängigkeiten und bleiben frei allozierbar.\n</li></ul>\n</li><li><strong>Reentrancy bei Client-Server-Ports:</strong>\n<ul class=\"fig-list\"><li>Obwohl hier 1:1 dargestellt, erfordert die Anbindung mehrerer Client-RPorts an denselben Server-PPort entweder eine reentrante Implementierung der Server-Runnable (<code>canBeInvokedConcurrently = true</code>) oder eine Pufferung/Serialisierung über RTE- und OS-Task-Warteschlangen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-3337a4f045fa58ad", "to": "FIG-55b9c79599ee40e0", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Ports <code>nv</code> an den Instanzen <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>: Port-Symbolisierung von einem gefüllten Halbkreis mit Querstrich auf ein nach oben zeigendes Dreiecks-Symbol geändert.\n</li></ul>"}, {"from": "FIG-55b9c79599ee40e0", "to": "FIG-c16909950dae22b7", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Ports <code>ecuMode</code> an den Instanzen <code>SHCFrontLeft</code> und <code>SHCFrontRight</code>: Port-Symbolisierung von einem gefüllten Dreiecks-Symbol auf ein Quadrat mit drei Punkten (Mode-Switch-Symbolik) geändert.\n</li><li>Typ-Beschriftung an Komponente <code>PM</code>: Zeilenumbruch und Textlayout des Typnamens <code>PowerManagement</code> korrigiert/überarbeitet.\n</li></ul>"}, {"from": "FIG-c16909950dae22b7", "to": "FIG-36c5bcf8a93ffcd2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-36c5bcf8a93ffcd2", "to": "FIG-f8833a57302019fb", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
